def nest(flat):
    out = {}
    for key, value in sorted(flat.items()):
        node = out
        parts = key.split('.')
        for p in parts[:-1]:
            node = node.setdefault(p, {})
        node[parts[-1]] = value
    return out

for name, flat in (('en', EN), ('uk', UK), ('pl', PL)):
    with open(f'messages/{name}.json', 'w', encoding='utf-8') as f:
        json.dump(nest(flat), f, ensure_ascii=False, indent=2)
        f.write('\n')
missing = {'uk': sorted(set(EN) - set(UK)), 'pl': sorted(set(EN) - set(PL))}
extra = {'uk': sorted(set(UK) - set(EN)), 'pl': sorted(set(PL) - set(EN))}
print(len(EN), 'keys; missing', missing, 'extra', extra)
